SELECT id, tenant_id, actor_id, action, resource_type, resource_id, detail, created_at
FROM iam_audit_log
WHERE tenant_id = #{tenantId}

    AND actor_id = #{actorId}


    AND action = #{action}


    AND created_at >= #{from}


    AND created_at <= #{to}

ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM iam_audit_log
WHERE tenant_id = #{tenantId}
